#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases for data, cov and mean to
     improve alias analysis and enable better vectorization.
   - Reorder the mean-computation loops to traverse the data matrix
     row-by-row (contiguous access) while preserving the exact
     accumulation order for each mean entry.
   - Use row pointers and explicit pointer arithmetic in inner loops
     to reduce index recomputation overhead.
   - Keep the covariance accumulation in the original i/j/k nesting
     (k innermost) so each cov[i][j] element is held in a register
     during the full reduction, avoiding repeated loads/stores.
 */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases to help the compiler with
     alias analysis. We will only access the arrays through these
     pointers inside the kernel. */
  DATA_TYPE (*restrict data_)[m] = data;
  DATA_TYPE (*restrict cov_)[m]  = cov;
  DATA_TYPE *restrict mean_      = mean;

  const DATA_TYPE fn            = float_n;
  const DATA_TYPE fn_minus_one  = fn - SCALAR_VAL(1.0);

#pragma scop
  /* 1. Compute column means.
     Original code:
       for (j)
         mean[j] = 0;
         for (i) mean[j] += data[i][j];
         mean[j] /= float_n;
     That iterates down columns with a stride of m in memory.

     Here we:
       - Initialize all means to zero once.
       - Accumulate sums row-by-row for better spatial locality.
     For each mean_[j] the sequence of additions over i is still
     in strictly increasing i order (0 .. _PB_N-1), so the floating-
     point reduction order for each column is preserved. */

  /* Initialize means. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate sums over rows (row-major order). */
  for (i = 0; i < _PB_N; i++)
  {
    const DATA_TYPE *restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += row[j];
  }

  /* Scale by 1/float_n (same operation as original code). */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= fn;

  /* 2. Center the data matrix: data[i][j] -= mean[j].
     This loop already uses row-major traversal (j inner), which
     has good locality; we just make the aliasing explicit and
     keep the computation identical. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      row[j] -= mean_[j];
  }

  /* 3. Compute the covariance matrix on the centered data.
     We keep the loop nesting with k as the innermost loop, so that
     each cov[i][j] element is accumulated completely in a scalar
     register before being written back once. This avoids the heavy
     memory traffic that would result from making k the outer loop.

     For each (i,j), we perform:
       sum = 0;
       for (k) sum += data[k][i] * data[k][j];
       sum /= (float_n - 1);
       cov[i][j] = sum;
       cov[j][i] = sum;

     Exactly the same operations as in the original kernel, but we
     use explicit column pointers with stride m to reduce index
     arithmetic inside the innermost loop. */

  for (i = 0; i < _PB_M; i++)
  {
    for (j = i; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);

      /* Column pointers: element k of column i/j is at offset k*m. */
      const DATA_TYPE *restrict col_i = &data_[0][i];
      const DATA_TYPE *restrict col_j = &data_[0][j];

      for (k = 0; k < _PB_N; k++)
      {
        sum += (*col_i) * (*col_j);
        col_i += m;
        col_j += m;
      }

      /* Scale and symmetrize, as in the original code. */
      sum /= fn_minus_one;
      cov_[i][j] = sum;
      cov_[j][i] = sum;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
