      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
                 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimizations:
 *  - Compute column means in row-major order (better cache use, same
 *    per-element accumulation order in i).
 *  - Fuse centering with a transpose into a separate MxN buffer
 *    (dataT), so that each column becomes a contiguous row.
 *  - Compute the covariance using dot-products on the transposed,
 *    centered data, giving contiguous accesses in the reduction
 *    dimension and allowing efficient vectorization.
 *
 * Semantics:
 *  - For each mean[j], the sequence of additions over i remains
 *    in increasing i order; only operations for different j are
 *    interleaved.
 *  - For each covariance entry cov[i][j], the sequence of
 *    products over k remains in increasing k order, and the
 *    centered values used are exactly data[i][j]-mean[j].
 *  - The final cov matrix is mathematically identical to the
 *    original implementation.
 */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
                       DATA_TYPE float_n,
                       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
                       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
                       DATA_TYPE POLYBENCH_1D(mean,M,m),
                       DATA_TYPE POLYBENCH_2D(dataT,M,N,m,n))
{
  int i, j, k;

  /* Local restrict-qualified views to help the compiler with
     alias analysis. We only access the arrays through these
     pointers inside this function. */
  DATA_TYPE (* restrict data_)[M]   = data;
  DATA_TYPE (* restrict cov_)[M]    = cov;
  DATA_TYPE * restrict mean_        = mean;
  DATA_TYPE (* restrict dataT_)[N]  = dataT;

#pragma scop
  /* -----------------------------------------------------------
   * 1. Compute column means with row-major traversal
   *    mean[j] = (1/n) * sum_i data[i][j]
   * -------------------------------------------------------- */

  /* Initialize means. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate sums: outer loop on rows (i), inner on columns (j).
     For a fixed j, the additions on mean_[j] still occur in
     strictly increasing i order: 0,1,2,...,_PB_N-1. */
  for (i = 0; i < _PB_N; i++)
  {
    const DATA_TYPE *row = data_[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += row[j];
  }

  /* Final division by n. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;


  /* -----------------------------------------------------------
   * 2. Center the data and form a transposed copy
   *
   *    centered = data[i][j] - mean[j]
   *    data[i][j]   <- centered
   *    dataT[j][i]  <- centered   (transpose)
   *
   * This keeps "data" with centered values (as in the original
   * code) and builds a cache-friendly transposed view "dataT"
   * for the covariance computation.
   * -------------------------------------------------------- */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *row        = data_[i];
    /* dataT_[j] is the j-th row of the transposed matrix. */
    for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE centered = row[j] - mean_[j];
      row[j]         = centered;
      dataT_[j][i]   = centered;  /* dataT has shape [M][N] */
    }
  }


  /* -----------------------------------------------------------
   * 3. Covariance computation
   *
   * Using centered, transposed data:
   *   cov[i][j] = (1/(n-1)) * sum_k dataT[i][k] * dataT[j][k]
   *
   * For each (i,j), k still increases from 0.._PB_N-1 exactly
   * as in the original implementation. Only the memory layout
   * is changed to improve locality and vectorization.
   * -------------------------------------------------------- */
  const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

  for (i = 0; i < _PB_M; i++)
  {
    const DATA_TYPE *row_i = dataT_[i];
    DATA_TYPE *cov_row_i   = cov_[i];

    for (j = i; j < _PB_M; j++)
    {
      const DATA_TYPE *row_j = dataT_[j];

      DATA_TYPE sum = SCALAR_VAL(0.0);

      /* Contiguous access in k for both row_i and row_j. */
      for (k = 0; k < _PB_N; k++)
        sum += row_i[k] * row_j[k];

      DATA_TYPE c = sum / denom;
      cov_row_i[j] = c;
      cov_[j][i]   = c;  /* enforce symmetry */
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  /* Transposed, centered copy of data: shape MxN. */
  POLYBENCH_2D_ARRAY_DECL(dataT,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
                     POLYBENCH_ARRAY(data),
                     POLYBENCH_ARRAY(cov),
                     POLYBENCH_ARRAY(mean),
                     POLYBENCH_ARRAY(dataT));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(dataT);

  return 0;
}
