      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop

  /* -----------------------------------------------------------
   * 1. Compute column means.
   *
   * Original code (column-major access, poor locality):
   *   for (j = 0; j < M; j++) {
   *     mean[j] = 0;
   *     for (i = 0; i < N; i++)
   *       mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *   }
   *
   * Optimized version:
   *   - Zero the whole mean[] array first.
   *   - Accumulate row by row with j as the inner loop.
   *   - Finally divide each mean[j] by float_n.
   *
   * For each fixed j, the sequence of additions is still:
   *   mean[j] = 0;
   *   for i = 0..N-1: mean[j] += data[i][j];
   * so the order of floating-point operations for each mean[j]
   * is preserved. Operations for different j values are simply
   * interleaved, which is semantically safe.
   *
   * This transformation greatly improves spatial locality on
   * 'data' (unit-stride over j) and keeps mean[] hot in cache.
   * ----------------------------------------------------------- */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_i = &data[i][0];
      for (j = 0; j < _PB_M; j++)
        mean[j] += data_i[j];
    }

  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;

  /* -----------------------------------------------------------
   * 2. Center the data matrix: subtract the mean from each column.
   *
   * This loop was already in a cache-friendly, row-major order.
   * We keep that structure and just hoist the row pointer to
   * reduce address arithmetic and aid vectorization.
   * ----------------------------------------------------------- */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_i = &data[i][0];
      for (j = 0; j < _PB_M; j++)
        data_i[j] -= mean[j];
    }

  /* -----------------------------------------------------------
   * 3. Compute the covariance matrix.
   *
   * Original structure:
   *   for (i = 0; i < M; i++)
   *     for (j = i; j < M; j++) {
   *       cov[i][j] = 0;
   *       for (k = 0; k < N; k++)
   *         cov[i][j] += data[k][i] * data[k][j];
   *       cov[i][j] /= (float_n - 1);
   *       cov[j][i] = cov[i][j];
   *     }
   *
   * This scans the N rows of 'data' once for every (i,j) pair,
   * giving very poor cache reuse on 'data'.
   *
   * Optimized structure below:
   *   3a) Zero the upper triangle of cov.
   *   3b) Outer loop over k (rows of 'data'):
   *         - For each row k, walk i and j with j as the
   *           innermost loop, which provides unit-stride
   *           accesses to both data[k][j] and cov[i][j].
   *   3c) Scale by (float_n - 1) and fill the symmetric part.
   *
   * Semantics:
   *   For each (i,j), the sequence of operations is still:
   *     cov[i][j] = 0;
   *     for k = 0..N-1: cov[i][j] += data[k][i]*data[k][j];
   *     cov[i][j] /= (float_n - 1);
   *     cov[j][i]  = cov[i][j];
   *
   *   We have only interleaved operations for different (i,j)
   *   pairs; the per-element order of floating-point additions
   *   over k is unchanged, so the numerical semantics are
   *   preserved.
   * ----------------------------------------------------------- */

  /* 3a. Zero upper triangle (including diagonal). */
  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE *cov_i = &cov[i][0];
      for (j = i; j < _PB_M; j++)
        cov_i[j] = SCALAR_VAL(0.0);
    }

  /* 3b. Accumulate outer products row by row. */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE *data_k = &data[k][0];

      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE dki = data_k[i];
          DATA_TYPE *cov_i = &cov[i][0];

          /* Inner j-loop:
           *  - cov_i[j] is contiguous along j
           *  - data_k[j] is also contiguous along j
           * This pattern is very amenable to SIMD/vectorization.
           */
          for (j = i; j < _PB_M; j++)
            cov_i[j] += dki * data_k[j];
        }
    }

  /* 3c. Scale by (float_n - 1.0) and enforce symmetry. */
  {
    DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

    for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE *cov_i = &cov[i][0];
        for (j = i; j < _PB_M; j++)
          {
            cov_i[j] /= denom;
            cov[j][i] = cov_i[j];
          }
      }
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

