      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance [[gnu::flatten, gnu::noinline]] (int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Allocate a temporary matrix that holds the mean-centered data in
   * transposed form: dataT[j * n + i] == data[i][j] after centering.
   *
   * In this layout, each original column becomes a contiguous row,
   * which makes the covariance computation (many dot products between
   * columns) much more cache-friendly and easier to vectorize.
   *
   * Size: m x n == M x N.
   */
  DATA_TYPE* dataT = (DATA_TYPE*)
    polybench_alloc_data((unsigned long long)m * (unsigned long long)n,
                         sizeof(DATA_TYPE));
  const unsigned long long nn = (unsigned long long)n;

#pragma scop
  /* 1. Compute column means.
   *
   * Original version:
   *   for j in 0..M-1:
   *     mean[j] = 0;
   *     for i in 0..N-1:
   *       mean[j] += data[i][j];
   *
   * That accesses data column-wise with a large stride. Here we
   * traverse the matrix row-wise (i outer, j inner), which is
   * contiguous in memory for row-major storage.
   */

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  /* Accumulate sums for each column using row-major traversal. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE* __restrict__ row = &data[i][0];
    for (j = 0; j < _PB_M; j++)
      mean[j] += row[j];
  }

  /* Scale by 1 / float_n (precompute reciprocal to avoid repeated divisions). */
  const DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  for (j = 0; j < _PB_M; j++)
    mean[j] *= inv_float_n;

  /* 2. Mean-center the data and build the transposed copy.
   *
   * Original version:
   *   for i in 0..N-1:
   *     for j in 0..M-1:
   *       data[i][j] -= mean[j];
   *
   * Here we do the same operation, but at the same time we store the
   * centered values into dataT so that columns of "data" become
   * contiguous rows in "dataT".
   *
   * Layout of dataT:
   *   dataT[j * n + i] == centered value of original data[i][j]
   */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE* __restrict__ row = &data[i][0];

    for (j = 0; j < _PB_M; j++)
    {
      const DATA_TYPE centered = row[j] - mean[j];
      row[j] = centered;

      /* Store into transposed buffer: row index j, column index i. */
      unsigned long long idx = (unsigned long long)j * nn + (unsigned long long)i;
      dataT[idx] = centered;
    }
  }

  /* 3. Compute covariance matrix.
   *
   * Mathematically, cov = (1 / (float_n - 1)) * X^T * X
   * where X is the mean-centered data of size N x M.
   *
   * After building dataT, each original column i corresponds to the
   * contiguous row:
   *   col_i[k] = dataT[i * n + k] = data[k][i]
   *
   * We therefore compute:
   *   cov[i][j] = (1 / (float_n - 1)) * sum_k col_i[k] * col_j[k]
   *
   * This is the same computation as the original code, but now the
   * inner dot products access contiguous memory, which improves data
   * locality and SIMD vectorization.
   */

  const DATA_TYPE norm_factor =
    SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));

  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE* __restrict__ col_i =
      &dataT[(unsigned long long)i * nn];

    for (j = i; j < _PB_M; j++)
    {
      DATA_TYPE* __restrict__ col_j =
        &dataT[(unsigned long long)j * nn];

      DATA_TYPE sum = SCALAR_VAL(0.0);

      /* Dot product between column i and column j. */
      for (k = 0; k < _PB_N; k++)
        sum += col_i[k] * col_j[k];

      sum *= norm_factor;
      cov[i][j] = sum;
      cov[j][i] = sum;
    }
  }
#pragma endscop

  /* Free temporary transposed buffer. */
  polybench_free_data(dataT);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
